    "content": "2026年11月15日 青海湟源县人民医院院史馆，摆放着一台老CT机。“这是县里第一台CT机。”院长黄炯抚摸着泛黄的机身感慨。 这台老CT机不仅造福了湟源百姓，更见证了一段跨越国界的友谊。 “这是大卫先生在2000年捐赠给县医院的。”那会儿，黄炯刚到县医院工作，“我从小在湟源长大，听说过很多大卫先生捐赠医疗设备的故事。” 美国人柏大卫，1931年出生，刚满周岁时随父母来到湟源，在这里长大成人。柏大卫说，湟源是他“唯一的故乡”。湟源人也亲切地唤他“大卫先生”。1987年重返湟源后，柏大卫开始一趟趟筹资，为故乡捐赠医疗…"
