    "description": "2026年11月15日 “‘闹’（湟源方言“我”）永远是湟源的娃。”这句地道的高原乡音，出自美国老人柏大卫之口。在老人心里，青海湟源不仅是曾经的居住地，更是心灵的故乡。 湟源大地铭记这份跨越重洋的情谊：县医院院史馆内，静静矗立着他奔走筹措捐赠的CT机；古城街巷间流传的童谣，至今还诉说着这位“湟源娃”的故事。一名大洋彼岸并不富足的普通人，数十年如一日地向湟源传递温暖，这印证了一个朴素的道理：国之交在于民相亲，民相亲在于心相通。 1908年…",
    "content": "2026年11月15日 “‘闹’（湟源方言“我”）永远是湟源的娃。”这句地道的高原乡音，出自美国老人柏大卫之口。在老人心里，青海湟源不仅是曾经的居住地，更是心灵的故乡。 湟源大地铭记这份跨越重洋的情谊：县医院院史馆内，静静矗立着他奔走筹措捐赠的CT机；古城街巷间流传的童谣，至今还诉说着这位“湟源娃”的故事。一名大洋彼岸并不富足的普通人，数十年如一日地向湟源传递温暖，这印证了一个朴素的道理：国之交在于民相亲，民相亲在于心相通。 1908年，柏大卫的父亲柏立美来到中国。在湟源扎根近30年，他学会汉语、藏语，免费为各族群…"
