    "description": "2026年11月15日 “在人生的黄昏里，要继续发光”“年龄只是数字，心气儿不倒，人生处处是舞台”……采访老年大学学员，听他们分享学习感悟，那种蓬勃的生命力让人动容。老年是生命的重要阶段，可以有作为、有进步、有快乐。 对许多人而言，人生的前半程，学习往往有明确目的：或为考试、为升学，或为证书、为职称。在老年大学，笔者却看到，学习是一件快乐的事，指向的是自由而全面的发展。有人重拾年轻时的爱好，有人好奇社会上的新鲜事物，银发学员主动走进课堂…",
    "content": "2026年11月15日 “在人生的黄昏里，要继续发光”“年龄只是数字，心气儿不倒，人生处处是舞台”……采访老年大学学员，听他们分享学习感悟，那种蓬勃的生命力让人动容。老年是生命的重要阶段，可以有作为、有进步、有快乐。 对许多人而言，人生的前半程，学习往往有明确目的：或为考试、为升学，或为证书、为职称。在老年大学，笔者却看到，学习是一件快乐的事，指向的是自由而全面的发展。有人重拾年轻时的爱好，有人好奇社会上的新鲜事物，银发学员主动走进课堂，上课不是任务，是盼头。 学有所乐，不仅在自我提升。老年教育不仅传授知识、技能，…"
