    "description": "2026年11月15日 日前，澳门大学（以下简称“澳大”）迎来建校45年。 从回归初期“有校无园”，到如今成长为国际化综合性研究型大学，澳大跨越式发展的背后，正是充分发挥“一国两制”制度优势，破解空间发展难题、加快搭建跨境科研平台、为学校建设持续注入更大势能的生动实践。 立法授权，让澳大告别“有校无园”历史。澳门回归祖国初期，澳大蜗居于氹仔山坳，本地学生平均每天来校1.6次，早来晚走，中午还要回家一趟，被调侃为“社区大学”。2009年6…",
    "content": "2026年11月15日 日前，澳门大学（以下简称“澳大”）迎来建校45年。 从回归初期“有校无园”，到如今成长为国际化综合性研究型大学，澳大跨越式发展的背后，正是充分发挥“一国两制”制度优势，破解空间发展难题、加快搭建跨境科研平台、为学校建设持续注入更大势能的生动实践。 立法授权，让澳大告别“有校无园”历史。澳门回归祖国初期，澳大蜗居于氹仔山坳，本地学生平均每天来校1.6次，早来晚走，中午还要回家一趟，被调侃为“社区大学”。2009年6月27日，十一届全国人大常委会通过《关于授权澳门特别行政区对设在横琴岛的澳门大学…"
