    "content": "2026年11月15日 日前，2026粤港澳大湾区全球招商大会在广东举办。粤港澳三地携手，延续“投资大湾区，共创美好未来”的主题，抢抓APEC“中国年”机遇，为海内外企业投资合作搭建广阔舞台，推动更多全球资本、优质项目、高层次人才向大湾区汇聚。 开放，是大湾区的鲜明底色。粤港澳大湾区是我国开放程度最高、经济活力最强的区域之一，大会现场发布21个地市42个代表性重大投资项目，投资金额达1974亿元。本届大会注重加强与欧美日韩等发达国家和中东、东盟等新兴市场国家投资贸易合作，推动制造业与服务业协同发力，并先后走进美国、…"
