    "content": "2026年11月15日 高毅中国画《半条被子》。 \"> 习近平总书记在纪念中国工农红军长征胜利90周年大会上指出：“人民群众永远是党和人民军队的力量源泉和坚强后盾”。“半条被子”的故事，正是党同人民保持血肉联系的生动见证。 1934年11月，湖南汝城县沙洲村，3名女红军借宿村民徐解秀家中，屋内一贫如洗。寒夜里，女红军们和徐解秀及其幼子挤在一张小床上，合盖一条行军被。临走时，怕徐解秀母子寒冬难熬，3名女红军把仅有的这条被子剪下一半，留给了他们。老人后来常常感叹：“什么是共产党？共产党就是自己有一条被子，也要剪下半条给…"
