    "description": "2026年11月15日 2018年，习近平总书记给中央美术学院8位老教授回信，向他们致以诚挚的问候，并就做好美育工作，弘扬中华美育精神提出殷切期望。美术教育工作者如何“以大爱之心育莘莘学子，以大美之艺绘传世之作”？中央美术学院美术馆举办的“播种者”展览，通过回顾百岁老人伍必端的美育人生，为回答这一课题提供了一个鲜活而生动的实践样本。 在80余年创作生涯中，伍必端始终恪守“为老百姓而画”的朴素信条。他曾这样总结自己的艺术来路，“感谢生活，…",
    "content": "2026年11月15日 图为伍必端版画《黄山云起》。 \"> 2018年，习近平总书记给中央美术学院8位老教授回信，向他们致以诚挚的问候，并就做好美育工作，弘扬中华美育精神提出殷切期望。美术教育工作者如何“以大爱之心育莘莘学子，以大美之艺绘传世之作”？中央美术学院美术馆举办的“播种者”展览，通过回顾百岁老人伍必端的美育人生，为回答这一课题提供了一个鲜活而生动的实践样本。 在80余年创作生涯中，伍必端始终恪守“为老百姓而画”的朴素信条。他曾这样总结自己的艺术来路，“感谢生活，使我有幸跟画笔和刻刀结缘。它不但为我提供了从…"
