    "author": "",
    "description": "2026年11月15日 “冬，终也，万物收藏也。”立冬过后，北风渐紧，水始冰，地始冻，万物进入休养、敛藏状态。寒意本无形，古人却总有办法让人感知它。白居易写夜雪，只道“夜深知雪重，时闻折竹声”，没有直接写雪落的样子，寒气却已随着竹枝折断的轻响透进屋里。诗能如此，画又如何？ 很多冬景绘画中，常常有动物相伴，既是自然写照，又寓意希望。唐代刁光胤的《写生花卉册之乔松卧兔石罅流泉》（见图），是古人以小景写冬意的一件雅致之作。刁光胤擅画湖石花竹、…",
    "content": "2026年11月15日 扫描二维码，观看相关视频。 \"> “冬，终也，万物收藏也。”立冬过后，北风渐紧，水始冰，地始冻，万物进入休养、敛藏状态。寒意本无形，古人却总有办法让人感知它。白居易写夜雪，只道“夜深知雪重，时闻折竹声”，没有直接写雪落的样子，寒气却已随着竹枝折断的轻响透进屋里。诗能如此，画又如何？ 很多冬景绘画中，常常有动物相伴，既是自然写照，又寓意希望。唐代刁光胤的《写生花卉册之乔松卧兔石罅流泉》（见图），是古人以小景写冬意的一件雅致之作。刁光胤擅画湖石花竹、猫兔禽鸟，黄筌即出其门下，他的传世之作极少。这…"
