    "content": "2026年11月15日 艺术与公众的关系，是一个历久弥新的议题。当下，人们在欣赏艺术作品、获得文化知识外，表达自身经验、与他人沟通交流、参与共同创造，愈发成为迫切需求。面对这一需求，作为公共文化机构的美术馆不断进行深层次的功能调整，观看者的经验和参与受到更多关注。个人和群体以怎样的身份投入其中？他们的经验如何影响艺术的阐释和创造？这是美术馆进一步提升公共教育水平面临的重要课题。 这一课题的解决，有赖于美术馆打破传统的知识单向输出模式，将公众视为文化创造的参与者。广州美术学院美术馆发起的“共岗计划”，便是一次生动探索…"
