    "content": "俄罗斯总统新闻秘书佩斯科夫称，俄罗斯、中国、美国领导人将于下星期四（11月19日）在中国深圳举行三方会晤。 据俄罗斯卫星通讯社星期六（11月14日）报道，佩斯科夫说：“各方已达成一致，普京总统、习近平主席和特朗普总统将于11月19日举行三方会晤。此次会晤将在深圳亚太经合组织峰会期间举行。” 白宫也在早前宣布，美国总统特朗普、中国国家主席习近平和俄罗斯总统普京下星期四在深圳出席亚太经合组织首脑峰会期间，将举行三方会晤。 白宫发言人上星期五（13日）说：“特朗普总统已表明，他将讨论包括削减全球核武器在内的议题。总统认为…"
