    "description": "中共阳泉市委书记鞠振任山西省副省长，朱晓东、常书铭卸任。 综合中新社和澎湃新闻报道，山西省第十四届人民代表大会常务委员会第三十一次会议星期六（11月14日）举行第二次全体会议，表决通过了人事任免名单，决定任命鞠振为山西省副省长，决定免去朱晓东、常书铭的副省长职务。 公开资料显示，鞠振是天津人，生于1972年4月，历史学硕士学位，1991年12月加入中国共产党，1994年7月参加工作。 他曾任山西省政府外事侨务办副主任、党组成员，运城市委…",
    "content": "中共阳泉市委书记鞠振任山西省副省长，朱晓东、常书铭卸任。 综合中新社和澎湃新闻报道，山西省第十四届人民代表大会常务委员会第三十一次会议星期六（11月14日）举行第二次全体会议，表决通过了人事任免名单，决定任命鞠振为山西省副省长，决定免去朱晓东、常书铭的副省长职务。 公开资料显示，鞠振是天津人，生于1972年4月，历史学硕士学位，1991年12月加入中国共产党，1994年7月参加工作。 他曾任山西省政府外事侨务办副主任、党组成员，运城市委常委、河津市委书记，山西省农业农村厅党组书记、厅长，神农科技集团有限公司党委书记…"
