    "description": "“现在是中国人做短剧给美国人看。” 今年41岁的创业者乐乘，在美国硅谷待了两个星期后发出这样的感慨。“人工智能（AI）短剧，从应用平台到内容制作……背后挤满了中国团队。” 乐乘2024年离开阿里巴巴，在新加坡创立公司，向东南亚和美国的内容创作者提供AI短剧制作工具TopView。他观察到，中国玩家正将国内市场练就的短剧制作方法，连同AI工具和平台一起推向海外。 中国国内短剧市场竞争激烈，企业几年前已开始征战海外。新加坡国立大学东亚研究所…",
    "content": "“现在是中国人做短剧给美国人看。” 今年41岁的创业者乐乘，在美国硅谷待了两个星期后发出这样的感慨。“人工智能（AI）短剧，从应用平台到内容制作……背后挤满了中国团队。” 乐乘2024年离开阿里巴巴，在新加坡创立公司，向东南亚和美国的内容创作者提供AI短剧制作工具TopView。他观察到，中国玩家正将国内市场练就的短剧制作方法，连同AI工具和平台一起推向海外。 中国国内短剧市场竞争激烈，企业几年前已开始征战海外。新加坡国立大学东亚研究所今年2月的报告显示，全球收入最高的50款短剧应用中，41款来自中国开发商。 AI…"
