    "description": "新华社华盛顿11月14日电（记者颜亮）美国联邦航空局局长布赖恩·贝德福德14日说，全美航空运输预计15日晚能恢复正常。 在全国航班停飞引发航空出行混乱后，贝德福德14日向美国公众道歉，并称“最糟糕的时期已经过去”，全国航空运输预计15日晚能恢复正常。 据美媒14日报道，达美航空、美国联合航空和美国航空当天取消了约20%航班，捷蓝航空取消了约40%航班。 美国交通部长肖恩·达菲当天表示，正在调查此次通信故障是否由操作人员失误引发。故障发生…",
    "content": "新华社华盛顿11月14日电（记者颜亮）美国联邦航空局局长布赖恩·贝德福德14日说，全美航空运输预计15日晚能恢复正常。 在全国航班停飞引发航空出行混乱后，贝德福德14日向美国公众道歉，并称“最糟糕的时期已经过去”，全国航空运输预计15日晚能恢复正常。 据美媒14日报道，达美航空、美国联合航空和美国航空当天取消了约20%航班，捷蓝航空取消了约40%航班。 美国交通部长肖恩·达菲当天表示，正在调查此次通信故障是否由操作人员失误引发。故障发生时，美国联邦航空局的承包商正在进行通信线路升级，将铜缆更换为光纤。 美国联邦航空…"
