    "description": "新华社曼谷11月14日电（记者张崇防 常天童）11月14日，国务院总理李强在曼谷会见泰国国王哇集拉隆功。 李强转达习近平主席对哇集拉隆功国王的亲切问候。李强表示，去年，国王陛下对中国进行国事访问，习近平主席同国王陛下举行会晤，就推进中泰命运共同体建设达成重要共识。中方赞赏泰国王室长期重视并致力于促进中泰友好。“中泰一家亲”，这是中泰关系的独特优势，体现在两国各领域务实成果，特别是当前动荡国际形势下，中泰经贸合作逆势增长，尤为难能可贵。中…",
    "content": "新华社曼谷11月14日电（记者张崇防 常天童）11月14日，国务院总理李强在曼谷会见泰国国王哇集拉隆功。 李强转达习近平主席对哇集拉隆功国王的亲切问候。李强表示，去年，国王陛下对中国进行国事访问，习近平主席同国王陛下举行会晤，就推进中泰命运共同体建设达成重要共识。中方赞赏泰国王室长期重视并致力于促进中泰友好。“中泰一家亲”，这是中泰关系的独特优势，体现在两国各领域务实成果，特别是当前动荡国际形势下，中泰经贸合作逆势增长，尤为难能可贵。中方愿同泰方一道，遵循两国元首战略引领，继续密切交往，拓展投资、科技创新、新能源汽…"
