    "content": "新华社南京11月14日电（记者尚昊、王明玉）纪念孙中山先生诞辰160周年活动嘉宾团晋谒中山陵仪式14日上午在南京举行。 南京是伟大的民族英雄、伟大的爱国主义者、中国民主革命的伟大先驱孙中山先生就任临时大总统的地方，南京中山陵也是他的陵寝所在地。9时30分许，由孙中山先生海外亲属代表、友人后代和港澳台侨代表人士等组成的嘉宾团抵达中山陵。 10时许，主持人宣布晋谒仪式正式开始。面向孙中山先生像，嘉宾团全体肃立，静默1分钟，并敬献花篮，全国政协副主席、民革中央常务副主席何报翔和孙中山先生玄孙孙伟仁上前整理花篮缎带。随后，…"
