    "description": "新华社布鲁塞尔11月14日电（记者马悦然 张馨文）欧盟对外行动署14日发表声明，对加沙地带持续、严峻的人道主义危机表示严重关切，敦促以色列立即开放所有过境点，允许人道主义援助不受阻碍地进入加沙地带。 声明说，近期的严重洪灾和冬季恶劣天气进一步加剧加沙民众的生存困境。宣布停火已过去一年，但军事打击仍在持续，现有通行限制导致适宜住所、药品和医疗设备等基本物资持续短缺。 声明说，欧盟敦促以色列立即开放加沙地带所有边境口岸，允许人道主义援助等不…",
    "content": "新华社布鲁塞尔11月14日电（记者马悦然 张馨文）欧盟对外行动署14日发表声明，对加沙地带持续、严峻的人道主义危机表示严重关切，敦促以色列立即开放所有过境点，允许人道主义援助不受阻碍地进入加沙地带。 声明说，近期的严重洪灾和冬季恶劣天气进一步加剧加沙民众的生存困境。宣布停火已过去一年，但军事打击仍在持续，现有通行限制导致适宜住所、药品和医疗设备等基本物资持续短缺。 声明说，欧盟敦促以色列立即开放加沙地带所有边境口岸，允许人道主义援助等不受阻碍地进入加沙地带，并确保相关援助持续、大规模开展。声明还要求以色列保障联合国…"
