    "description": "新华社太原11月14日电（记者马晓洁）14日，由新华网、新华社山西分社主办的第13届新华网思客年会在山西省大同市举办。本次思客年会以“中国经济的下一程：向新而行 以质致远”为主题，来自政产学研用领域的参会人员围绕“十五五”时期的战略重点、新质生产力等内容分享观点，建言献策，共话经济高质量发展新路径。 新华社副社长、党组成员刘健在致辞中说，作为党的新闻舆论工作重镇，新华社始终坚持围绕中心、服务大局，是中国经济高质量发展的记录者、见证者、参…",
    "content": "新华社太原11月14日电（记者马晓洁）14日，由新华网、新华社山西分社主办的第13届新华网思客年会在山西省大同市举办。本次思客年会以“中国经济的下一程：向新而行 以质致远”为主题，来自政产学研用领域的参会人员围绕“十五五”时期的战略重点、新质生产力等内容分享观点，建言献策，共话经济高质量发展新路径。 新华社副社长、党组成员刘健在致辞中说，作为党的新闻舆论工作重镇，新华社始终坚持围绕中心、服务大局，是中国经济高质量发展的记录者、见证者、参与者。新华社将充分利用遍及全球的新闻信息采集传播网络和全媒体报道优势，为中国经济…"
