    "description": "新华社北京11月14日电 欧盟机构欧洲边境管理局13日发布的数据显示，今年前10个月，在欧盟边境截获的非法入境人数比去年同期下降29%，约为11万人次。 欧洲边境管理局说，今年前10个月，在几条主要的非法入境路线上，非法越境者均有所减少。欧盟委员会负责内政与移民事务的委员马格努斯·布伦纳将这一趋势归因于国际合作加强。 从具体路线看，北非至意大利的中地中海路线非法入境人数降幅最大，下降55%；东地中海路线截获的非法越境者占比最多，但与去年…",
    "content": "新华社北京11月14日电 欧盟机构欧洲边境管理局13日发布的数据显示，今年前10个月，在欧盟边境截获的非法入境人数比去年同期下降29%，约为11万人次。 欧洲边境管理局说，今年前10个月，在几条主要的非法入境路线上，非法越境者均有所减少。欧盟委员会负责内政与移民事务的委员马格努斯·布伦纳将这一趋势归因于国际合作加强。 从具体路线看，北非至意大利的中地中海路线非法入境人数降幅最大，下降55%；东地中海路线截获的非法越境者占比最多，但与去年同期相比也减少了约12%。 这是8月15日拍摄的西班牙休达与摩洛哥的海上隔离围栏…"
