    "title": "看展丨玄素之间，照见自己",
    "link": "http://www.news.cn/20261114/b953437b256e4d9db6216110f3a9de3c/c.html",
    "pub_date": "2026-11-14 20:40:08",
    "author": "",
    "description": "一道幽玄、一片素白。用色最少时，线条、肌理、刻痕都无处遁形。 “玄素”作品如何欣赏？北京画院院长吴洪亮给出的建议是：慢一点。先在一道刻痕前停住，看它的轻重；再在一片留白里待一会儿，感受它的呼吸；然后顺着犹疑或笃定的线条往下看。 近日，“玄素——中国黑白艺术研究”展览在山东美术馆正式面向公众开放，展期至12月13日。展览由清华大学美术学院主办，山东美术馆、清华大学美术学院美术馆承办，汇集尚扬、王怀庆、梁绍基、王冬龄、徐冰、施慧、闫平、隋建…",
    "content": "一道幽玄、一片素白。用色最少时，线条、肌理、刻痕都无处遁形。 “玄素”作品如何欣赏？北京画院院长吴洪亮给出的建议是：慢一点。先在一道刻痕前停住，看它的轻重；再在一片留白里待一会儿，感受它的呼吸；然后顺着犹疑或笃定的线条往下看。 近日，“玄素——中国黑白艺术研究”展览在山东美术馆正式面向公众开放，展期至12月13日。展览由清华大学美术学院主办，山东美术馆、清华大学美术学院美术馆承办，汇集尚扬、王怀庆、梁绍基、王冬龄、徐冰、施慧、闫平、隋建国、冷冰川、顾黎明、白明、马岩松12位艺术家的约60件作品，涵盖绘画、书法、雕塑…"
