    "description": "新华社香港11月14日电（谢妞）海风轻拂维港，位于香港上环的红头船风雨亭前人头攒动、场面热闹。由香港潮州商会主办的“阿嬷走近维港·侨批历史上的香港”分享活动14日在港举行。活动通过专题分享和文化体验等环节，带领市民认识香港在侨批历史中的重要角色，传承侨批所承载的家书情怀与华侨记忆。 活动现场，鼓点骤起，英歌舞队登台亮相，舞者脸谱鲜亮、槌棒翻飞、步伐矫健，铿锵节拍引来现场阵阵喝彩；歌手随后献唱《给阿嬷的情书》主题曲《月下煮茶》，旋律悠扬。…",
