    "content": "中国社会科学院副院长彭金辉出任中国国际经济交流中心理事长。 据中国社会科学网消息，中国国际经济交流中心星期四（11月12日）在北京举行第四届第一次会员大会暨理事会，选举产生新一届理事会。中国社会科学院副院长、党组副书记彭金辉当选理事长。 国经中心今年1月经历了重大管理体制调整，业务主管单位由国家发展和改革委员会变更为中国社会科学院。 中国社会科学院院长、党组书记高翔星期四也会见了新一届国经中心理事会领导班子成员和理事代表。高翔指出，2026年1月，国经中心整体划转到中国社会科学院，是党中央着眼深化智库体制机制改革、…"
