    "title": "能源通道瓦日铁路创年运量破亿吨最快纪录",
    "link": "http://www.news.cn/20261114/e954277d42be498a81326b8078cf1bcb/c.html",
    "pub_date": "2026-11-14 18:16:54",
    "author": "",
    "description": "新华社太原11月14日电（记者许雄）记者从晋豫鲁铁路通道股份有限公司获悉，截至11月13日，我国西煤东运大通道瓦日铁路2026年货运量达10026.299万吨。这是瓦日铁路自2022年以来第4年货运量迈上亿吨大关，较2025年提前35天达到亿吨运量目标，刷新线路年运量破亿吨用时最短纪录。 瓦日铁路西起山西省吕梁市兴县瓦塘镇，东至山东省日照市，全长1269公里，是我国首条一次性建成的30吨轴重重载铁路。线路穿越晋、豫、鲁三省，与京广、京九…",
    "content": "新华社太原11月14日电（记者许雄）记者从晋豫鲁铁路通道股份有限公司获悉，截至11月13日，我国西煤东运大通道瓦日铁路2026年货运量达10026.299万吨。这是瓦日铁路自2022年以来第4年货运量迈上亿吨大关，较2025年提前35天达到亿吨运量目标，刷新线路年运量破亿吨用时最短纪录。 瓦日铁路西起山西省吕梁市兴县瓦塘镇，东至山东省日照市，全长1269公里，是我国首条一次性建成的30吨轴重重载铁路。线路穿越晋、豫、鲁三省，与京广、京九、京沪等7大铁路干线及京杭大运河、黄海水路互联互通，是我国重要的能源入海重载运输…"
