    "content": "新华社深圳11月14日电（记者王丰、杨深深）记者14日从2026年APEC领导人会议周新闻中心首场吹风会上获悉，目前APEC深圳会议各项筹备工作已经就绪。 广东省委常委、APEC会议广东省筹备工作领导小组副组长王曦在会上介绍，亚太经合组织第三十三次领导人非正式会议将于2026年11月18日至19日在广东深圳举行。本次筹备工作突出绿色赋能，充分利用现有资源做好场馆改造提升，积极倡导绿色出行；突出文化赋能，将中华优秀传统文化、岭南文脉底蕴精心融入会场布置、文艺演出、餐饮服务等各个场景；突出科技赋能，将人工智能等数字技术…"
