    "description": "人这一生，无论走多远，最难磨灭的还是童年的风景。 丹噶尔城全景（1942年）照片后排戴白帽子的是柏大卫。 柏立美摄 这些细碎的童年记忆，经久萦绕在他的心头，成了难以割舍的乡愁。 盛夏，孩童们在河滩处“打搅洗”（游泳）（1942年摄）。 1932年，已过周岁的柏大卫跟随父亲柏立美不远万里来到这个陌生的国度，一住就是17年。他或许不会想到，这座高原小城竟成了他一生的牵挂。 儿时的柏大卫（左二）与父亲柏立美（左一）、母亲（右后）、妹妹（右前）…",
