    "content": "新华社北京11月14日电（高玉娇、邵朝鹏）人民空军14日组织试飞员代表走进清华大学宣讲，记者在现场获悉，空军多型战机试飞员将亮相第十六届中国航展，全方位展现新时代空军试飞队伍的风采。 14日，人民空军老中青三代试飞员群体代表——被中央军委授予“试飞英雄”荣誉称号的黄炳新、歼-20首席试飞员李刚和空军某部试飞员郑鑫，走进清华大学，讲述他们立志空天、为国试剑的奋斗故事，为青年学子带来一堂国防教育思政课。 此前，试飞员群体代表还在北京大学与北京航空航天大学开展了主题宣讲。作为培养高素质新型飞行人才的重要举措，空军自201…"
