    "content": "新华社曼谷11月14日电（记者刘畅 伍岳）11月14日，国务院总理李强在曼谷同泰国总理阿努廷共同出席中泰企业家座谈会。 李强听取两国企业界代表发言，表示当前中泰正携手开创两国关系新的金色50年，双方经贸合作面临更多新的契机。一是中泰高度互信友好带来的稳定效应。当今世界变乱交织，“稳定”成为稀缺资源。中泰关系与合作恰恰有很强稳定性，两国领导人保持密切良好沟通，两国民众人缘相亲、文化相通，这些为双方企业加大投资、进行长远规划提供了稳定、可预期的环境。二是互联互通日益加强带来的聚合效应。中泰铁路建设稳步推进，平陆运河正式…"
